import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))

    dist_matrix = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dist_matrix[i][i] = 0

    for start_node in range(1, n + 1):
        d = [float('inf')] * (n + 1)
        d[start_node] = 0
        q = deque([start_node])

        while q:
            u = q.popleft()
            current_dist = d[u]

            for v, w in adj[u]:
                if d[v] > current_dist + w:
                    d[v] = current_dist + w
                    q.append(v)

        for i in range(1, n + 1):
            dist_matrix[start_node][i] = d[i]

    result = []

    for s in range(1, n + 1):
        for t in range(s + 1, n + 1):
            if dist_matrix[s][t] == float('inf'):
                result.append(0)
                continue

            count = 0
            for u in range(1, n + 1):
                for v, w in adj[u]:
                    if v < u:
                        continue
                    if dist_matrix[s][u] + w + dist_matrix[v][t] == dist_matrix[s][t]:
                        count += 1
                    elif dist_matrix[s][v] + w + dist_matrix[u][t] == dist_matrix[s][t]:
                        count += 0

            result.append(count)

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
